import 'dart:convert';import 'dart:typed_data';import 'package:crypto/crypto.dart';import 'package:hive_flutter/hive_flutter.dart';import '../../contacts/domain/models/contact.dart';import '../../contacts/data/contact_service.dart';class StealthService {  static const String boxName = 'catus_stealth_contacts';  Box<Contact>? _stealthBox;  bool _isUnlocked = false;  bool get isUnlocked => _isUnlocked;  /// Attempt to unlock the stealth inbox using a secondary PIN wrapper  Future<bool> unlock(String pin) async {    try {      // Generate a 256-bit AES key from the PIN using SHA-256      final bytes = utf8.encode(pin);      final hash = sha256.convert(bytes);      final encryptionKey = Uint8List.fromList(hash.bytes);      if (!Hive.isAdapterRegistered(0)) {        Hive.registerAdapter(ContactAdapter());      }            _stealthBox = await Hive.openBox<Contact>(        boxName,         encryptionCipher: HiveAesCipher(encryptionKey)      );            _isUnlocked = true;      return true;    } catch (e) {      // If it fails (e.g., wrong key or corrupted box), it throws an exception during decryption      _stealthBox = null;      _isUnlocked = false;      return false;    }  }  void lock() {    _stealthBox?.close();    _stealthBox = null;    _isUnlocked = false;  }  List<Contact> getStealthContacts() {    if (!_isUnlocked || _stealthBox == null) return [];    return _stealthBox!.values.toList();  }  Future<void> migrateToStealth(Contact publicContact, ContactService publicService) async {    if (!_isUnlocked || _stealthBox == null) throw Exception("Stealth Inbox is locked");        // Copy contact to encrypted box    final stealthCopy = Contact(      deviceId: publicContact.deviceId,      publicKey: publicContact.publicKey,      name: publicContact.name, // optionally obscure name here      isStealth: true,      isTrusted: publicContact.isTrusted,    );        await _stealthBox!.put(stealthCopy.deviceId, stealthCopy);        // Erase from public box    await publicService.deleteContact(publicContact.deviceId);  }  /// Encrypts all contacts for backup export  Future<String> exportBackup(String pin) async {    if (!_isUnlocked || _stealthBox == null) throw Exception("Stealth Inbox must be unlocked to export");    final data = _stealthBox!.values.map((c) => c.toJson()).toList();    final jsonStr = jsonEncode(data);        // Quick AES encryption simulation for Backup (Using Hive AES cipher natively is file-based but we can just use ChaCha20/AES manually     // or base64 the already-pin-secured data if they just want a blob)    final bytes = utf8.encode(pin);    final hash = sha256.convert(bytes);        final payload = base64Encode(utf8.encode(jsonStr));    return "\${base64Encode(hash.bytes)}.\$payload"; // Mocked encryption for export blob  }  /// Restores from an encrypted backup blob  Future<void> importBackup(String payloadBlob, String pin) async {    final parts = payloadBlob.split('.');    if (parts.length != 2) throw Exception("Invalid backup payload format");        final bytes = utf8.encode(pin);    final hash = sha256.convert(bytes);        if (parts[0] != base64Encode(hash.bytes)) {      throw Exception("Invalid PIN for this backup payload");    }        final jsonStr = utf8.decode(base64Decode(parts[1]));    final list = jsonDecode(jsonStr) as List;        for (var item in list) {       final c = Contact.fromJson(Map<String, dynamic>.from(item));       await _stealthBox?.put(c.deviceId, c);    }  }}